    58	Object Object::copy() const {
    59	  CHECK_NOT_DEAD;
    60	
    61	  Object obj;
    62	  std::memcpy(reinterpret_cast<void*>(&obj), this, sizeof(Object));
    63	
    64	  switch (type) {
    65	  case objString:
    66	    obj.string = string->copy();
    67	    break;
    68	  case objName:
    69	  case objCmd:
    70	    obj.cString = copyString(cString);
    71	    break;
    72	  case objArray:
    73	    array->incRef();
    74	    break;
    75	  case objDict:
    76	    dict->incRef();
    77	    break;
    78	  case objStream:
    79	    stream->incRef();
    80	    break;
    81	  default:
    82	    break;
    83	  }
    84	
    85	  return obj;
    86	}
    87	
    88	Object Object::fetch(XRef *xref, int recursion) const {
    89	  CHECK_NOT_DEAD;
    90	
    91	  return (type == objRef && xref) ?
    92	         xref->fetch(ref, recursion) : copy();
    93	}
    94	
    95	void Object::free() {
    96	  switch (type) {
    97	  case objString:
    98	    delete string;
    99	    break;
   100	  case objName:
   101	  case objCmd:
   102	    gfree(cString);
   103	    break;
   104	  case objArray:
   105	    if (!array->decRef()) {
   106	      delete array;
   107	    }
   108	    break;
   109	  case objDict:
   110	    if (!dict->decRef()) {
   111	      delete dict;
   112	    }
   113	    break;
   114	  case objStream:
   115	    if (!stream->decRef()) {
   116	      delete stream;
   117	    }
   118	    break;
   119	  default:
   120	    break;
   121	  }
   122	  type = objNone;
   123	}
   124	
   125	const char *Object::getTypeName() const {
   126	  return objTypeNames[type];
   127	}
