   129	void Object::print(FILE *f) const {
   130	  int i;
   131	
   132	  switch (type) {
   133	  case objBool:
   134	    fprintf(f, "%s", booln ? "true" : "false");
   135	    break;
   136	  case objInt:
   137	    fprintf(f, "%d", intg);
   138	    break;
   139	  case objReal:
   140	    fprintf(f, "%g", real);
   141	    break;
   142	  case objString:
   143	    fprintf(f, "(");
   144	    fwrite(string->c_str(), 1, string->getLength(), f);
   145	    fprintf(f, ")");
   146	    break;
   147	  case objName:
   148	    fprintf(f, "/%s", cString);
   149	    break;
   150	  case objNull:
   151	    fprintf(f, "null");
   152	    break;
   153	  case objArray:
   154	    fprintf(f, "[");
   155	    for (i = 0; i < arrayGetLength(); ++i) {
   156	      if (i > 0)
   157	        fprintf(f, " ");
   158	      const Object &obj = arrayGetNF(i);
   159	      obj.print(f);
   160	    }
   161	    fprintf(f, "]");
   162	    break;
   163	  case objDict:
   164	    fprintf(f, "<<");
   165	    for (i = 0; i < dictGetLength(); ++i) {
   166	      fprintf(f, " /%s ", dictGetKey(i));
   167	      const Object &obj = dictGetValNF(i);
   168	      obj.print(f);
   169	    }
   170	    fprintf(f, " >>");
   171	    break;
   172	  case objStream:
   173	    fprintf(f, "<stream>");
   174	    break;
   175	  case objRef:
   176	    fprintf(f, "%d %d R", ref.num, ref.gen);
   177	    break;
   178	  case objCmd:
   179	    fprintf(f, "%s", cString);
   180	    break;
   181	  case objError:
   182	    fprintf(f, "<error>");
   183	    break;
   184	  case objEOF:
   185	    fprintf(f, "<EOF>");
   186	    break;
   187	  case objNone:
   188	    fprintf(f, "<none>");
   189	    break;
   190	    case objDead:
   191	    fprintf(f, "<dead>");
   192	    break;
   193	  case objInt64:
   194	    fprintf(f, "%lld", int64g);
   195	    break;
   196	  }
